solution.solution.cpp:
#include <cctype>
#include <cstdint>
#include <optional>
#include <string>
#include <vector>

enum class Stream { Out, Err };
struct Chunk { Stream stream; std::string bytes; };
struct Diagnostic { std::string file; int line; int column; std::string severity; std::string code; std::string message; };
struct BuildResult { std::vector<std::string> outLines, errLines; std::vector<Diagnostic> diagnostics; int errors, warnings; bool succeeded; std::string status; };

static bool digits(const std::string& s) { if (s.empty()) return false; for (char c : s) if (!std::isdigit(static_cast<unsigned char>(c))) return false; return true; }

static std::optional<Diagnostic> afterLocation(Diagnostic d, const std::string& rest)
{
    // rest looks like "error C2065: message" or "error: message"
    for (const char* sev : { "error", "warning", "note" })
    {
        const std::string s{ sev };
        if (rest.compare(0, s.size(), s) != 0) continue;
        std::size_t at{ s.size() };
        if (at < rest.size() && rest[at] == ' ')
        {
            const std::size_t colon{ rest.find(':', at) };
            if (colon == std::string::npos) return std::nullopt;
            const std::string code{ rest.substr(at + 1, colon - at - 1) };
            if (code.size() < 2 || !std::isalpha(static_cast<unsigned char>(code[0])) || !digits(code.substr(1))) return std::nullopt;
            d.code = code;
            at = colon;
        }
        if (at >= rest.size() || rest[at] != ':') return std::nullopt;
        d.severity = s;
        d.message = rest.substr(at + 1);
        if (!d.message.empty() && d.message[0] == ' ') d.message.erase(0, 1);
        return d;
    }
    return std::nullopt;
}

std::optional<Diagnostic> parseDiagnostic(const std::string& line)
{
    const std::size_t from{ line.size() > 2 && line[1] == ':' ? 2u : 0u };
    // MSVC: file(line[,col]): rest
    const std::size_t paren{ line.find('(', from) };
    if (paren != std::string::npos)
    {
        const std::size_t close{ line.find("): ", paren) };
        if (close != std::string::npos)
        {
            const std::string inside{ line.substr(paren + 1, close - paren - 1) };
            const std::size_t comma{ inside.find(',') };
            const std::string l{ inside.substr(0, comma) }, c{ comma == std::string::npos ? "" : inside.substr(comma + 1) };
            if (digits(l) && (c.empty() || digits(c)))
                return afterLocation({ line.substr(0, paren), std::stoi(l), c.empty() ? 0 : std::stoi(c), "", "", "" }, line.substr(close + 3));
        }
    }
    // Clang: file:line:col: rest
    const std::size_t c1{ line.find(':', from) };
    if (c1 == std::string::npos) return std::nullopt;
    const std::size_t c2{ line.find(':', c1 + 1) }, c3{ c2 == std::string::npos ? c2 : line.find(':', c2 + 1) };
    if (c3 == std::string::npos || c3 + 2 > line.size() || line[c3 + 1] != ' ') return std::nullopt;
    const std::string l{ line.substr(c1 + 1, c2 - c1 - 1) }, c{ line.substr(c2 + 1, c3 - c2 - 1) };
    if (!digits(l) || !digits(c)) return std::nullopt;
    return afterLocation({ line.substr(0, c1), std::stoi(l), std::stoi(c), "", "", "" }, line.substr(c3 + 2));
}

static std::vector<std::string> linesOf(const std::vector<Chunk>& chunks, Stream which)
{
    std::vector<std::string> lines;
    std::string partial;
    for (const Chunk& ch : chunks)
    {
        if (ch.stream != which) continue;
        for (char c : ch.bytes)
        {
            if (c != '\n') { partial += c; continue; }
            if (!partial.empty() && partial.back() == '\r') partial.pop_back();
            lines.push_back(partial);
            partial.clear();
        }
    }
    if (!partial.empty()) { if (partial.back() == '\r') partial.pop_back(); lines.push_back(partial); }
    return lines;
}

BuildResult collect(const std::vector<Chunk>& chunks, std::uint32_t exitCode)
{
    BuildResult r{ linesOf(chunks, Stream::Out), linesOf(chunks, Stream::Err), {}, 0, 0, false, "" };
    for (const auto* list : { &r.outLines, &r.errLines })
        for (const std::string& line : *list)
            if (const auto d{ parseDiagnostic(line) })
            {
                r.diagnostics.push_back(*d);
                if (d->severity == "error") ++r.errors;
                if (d->severity == "warning") ++r.warnings;
            }
    r.succeeded = exitCode == 0 && r.errors == 0;
    if ((exitCode & 0xC0000000u) == 0xC0000000u)
    {
        static const char* const HEX{ "0123456789ABCDEF" };
        r.status = "compiler crashed: 0x";
        for (int i{ 7 }; i >= 0; --i) r.status += HEX[(exitCode >> (4 * i)) & 0xF];
    }
    else if (r.succeeded) r.status = "succeeded";
    else if (r.errors > 0) r.status = "failed: " + std::to_string(r.errors) + " errors";
    else r.status = "failed: exit code " + std::to_string(exitCode);
    return r;
}

unitTests:
TEST("MSVC diagnostics") {
    const auto d{ parseDiagnostic("C:\\src\\game.cpp(12,5): error C2065: 'hp': undeclared identifier") };
    CHECK(d.has_value());
    if (!d) return;
    CHECK_EQ(d->file, std::string("C:\\src\\game.cpp"));
    CHECK_EQ(d->line, 12); CHECK_EQ(d->column, 5);
    CHECK_EQ(d->severity, std::string("error")); CHECK_EQ(d->code, std::string("C2065"));
    CHECK_EQ(d->message, std::string("'hp': undeclared identifier"));
    const auto w{ parseDiagnostic("C:\\src\\game.cpp(40): warning C4244: 'argument': conversion from 'double' to 'int'") };
    CHECK(w.has_value());
    if (w) { CHECK_EQ(w->column, 0); CHECK_EQ(w->message, std::string("'argument': conversion from 'double' to 'int'")); }
}
TEST("Clang diagnostics") {
    const auto d{ parseDiagnostic("src/main.cpp:7:3: error: expected ';' after expression") };
    CHECK(d.has_value());
    if (d) { CHECK_EQ(d->file, std::string("src/main.cpp")); CHECK_EQ(d->line, 7); CHECK_EQ(d->column, 3); CHECK_EQ(d->code, std::string("")); CHECK_EQ(d->message, std::string("expected ';' after expression")); }
    const auto n{ parseDiagnostic("C:/src/main.cpp:9:1: note: to match this '{'") };
    CHECK(n.has_value());
    if (n) { CHECK_EQ(n->file, std::string("C:/src/main.cpp")); CHECK_EQ(n->severity, std::string("note")); }
}
TEST("not diagnostics") {
    CHECK(!parseDiagnostic("Microsoft (R) C/C++ Optimizing Compiler").has_value());
    CHECK(!parseDiagnostic("game.cpp").has_value());
    CHECK(!parseDiagnostic("time: 12:30:15: fine").has_value());
    CHECK(!parseDiagnostic("C:\\a.cpp(x): error C1: no").has_value());
    CHECK(!parseDiagnostic("a.cpp(3): info: hello").has_value());
}
TEST("collecting a failed build") {
    const std::vector<Chunk> chunks{
        { Stream::Out, "game.cpp\r\nC:\\src\\game.cpp(12,5): error C2065: 'hp': undec" },
        { Stream::Err, "src/x.cpp:1:1: warn" },
        { Stream::Out, "lared identifier\r\nC:\\src\\game.cpp(40): warning C4244: 'argument': conversion\r\n" },
        { Stream::Err, "ing: unused\n" },
    };
    const BuildResult r{ collect(chunks, 2) };
    CHECK_EQ(r.outLines.size(), 3u);
    CHECK_EQ(r.errLines.size(), 1u);
    CHECK_EQ(r.diagnostics.size(), 3u);
    CHECK_EQ(r.errors, 1); CHECK_EQ(r.warnings, 2);
    CHECK(!r.succeeded);
    CHECK_EQ(r.status, std::string("failed: 1 errors"));
}
TEST("success, crashes and silent failures") {
    CHECK_EQ(collect({ { Stream::Out, "game.cpp\r\n" } }, 0).status, std::string("succeeded"));
    CHECK(collect({}, 0).succeeded);
    CHECK_EQ(collect({}, 0xC0000005u).status, std::string("compiler crashed: 0xC0000005"));
    CHECK_EQ(collect({ { Stream::Err, "LINK : fatal error LNK1104: cannot open file" } }, 1104).status, std::string("failed: exit code 1104"));
}

